<?php require 'common.php';require_admin();$site=site();$fields=['name'=>'Display name','role'=>'Role / headline','about'=>'About me','email'=>'Contact email','location'=>'Location (optional; leave blank to hide)','facebook'=>'Facebook URL','github'=>'GitHub URL','skills'=>'Skills (one per line)'];$saved=false;if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$stmt=$db->prepare('REPLACE INTO settings(`key`,value) VALUES(?,?)');foreach($fields as $key=>$label){$v=trim((string)($_POST[$key]??''));if(in_array($key,['facebook','github'],true)) $v=safe_url($v);if($key==='skills'){$v=json_encode(array_values(array_filter(array_map('trim',preg_split('/\r?\n/',$v)))));} $stmt->execute([$key,$v]);}header('Location: settings.php?saved=1');exit;}layout_start('Edit portfolio details');?><div class="panel narrow wide"><?php if(isset($_GET['saved'])):?><p class="success">Portfolio details saved successfully.</p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><?php foreach($fields as $key=>$label):?><label><?=h($label)?><?php $value=$key==='skills'?implode("\n",(array)$site[$key]):$site[$key]; if(in_array($key,['about','skills'],true)):?><textarea name="<?=h($key)?>" rows="5"><?=h($value)?></textarea><?php else:?><input name="<?=h($key)?>" value="<?=h($value)?>" <?= $key==='email'?'type="email"':'' ?>><?php endif;?></label><?php endforeach;?><button class="primary">Save portfolio details</button></form></div><?php layout_end(); ?>
